def combinations_list(lst):
    result = []

    def backtrack(start, path):
        if len(path) > 0:
            result.append(list(path))

        for i in range(start, len(lst)):
            current_element = lst[i]

            # Add the element to the path and recurse with next index (to avoid duplicates within same level)
            backtrack(i + 1, path + [current_element])

    backtrack(0, [])
    return result
